using CourseManagementSystem.Data; using CourseManagementSystem.DTOs.Students; using CourseManagementSystem.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace CourseManagementSystem.Controllers; [ApiController][Route("api/[controller]")] public class StudentsController(ApplicationDbContext context):ControllerBase{
[HttpGet] public async Task<ActionResult<IEnumerable<StudentResponseDto>>> GetAll()=>Ok(await context.Students.AsNoTracking().OrderBy(x=>x.FullName).Select(x=>new StudentResponseDto(x.Id,x.FullName,x.Email,x.Phone)).ToListAsync());
[HttpGet("{id:int}")] public async Task<ActionResult<StudentResponseDto>> GetById(int id){var x=await context.Students.AsNoTracking().Where(x=>x.Id==id).Select(x=>new StudentResponseDto(x.Id,x.FullName,x.Email,x.Phone)).FirstOrDefaultAsync();return x is null?NotFound():Ok(x);}
[HttpPost] public async Task<ActionResult<StudentResponseDto>> Create(StudentCreateDto dto){if(await context.Students.AnyAsync(x=>x.Email==dto.Email))return Conflict(new{message="Email already exists."});var x=new Student{FullName=dto.FullName.Trim(),Email=dto.Email.Trim(),Phone=dto.Phone};context.Add(x);await context.SaveChangesAsync();var r=new StudentResponseDto(x.Id,x.FullName,x.Email,x.Phone);return CreatedAtAction(nameof(GetById),new{id=x.Id},r);}
[HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,StudentUpdateDto dto){var x=await context.Students.FindAsync(id);if(x is null)return NotFound();if(await context.Students.AnyAsync(s=>s.Id!=id&&s.Email==dto.Email))return Conflict(new{message="Email already exists."});x.FullName=dto.FullName.Trim();x.Email=dto.Email.Trim();x.Phone=dto.Phone;await context.SaveChangesAsync();return NoContent();}
[HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var x=await context.Students.FindAsync(id);if(x is null)return NotFound();if(await context.Enrollments.AnyAsync(e=>e.StudentId==id))return Conflict(new{message="Cannot delete a student with enrollments."});context.Remove(x);await context.SaveChangesAsync();return NoContent();}
}
